  R("old", "Former carton-based inventory", "The first Cobalt sheet treated one carton as one stock unit regardless of its contained quantity.", status="superseded", revision="r1"),
  R("change", "Piece-count migration", "Cobalt moved from carton units to individual-piece counts after suppliers changed package sizes. Carton metadata remained available for receiving staff.", kind="decision", supersedes=["old"]),
  R("paint", "Cobalt paint stock", "The paint-room task calls its blue pigment Cobalt and measures it in grams. Washer counts must not use this pigment's unit.", task="paint-room"),
  R("pref", "Vera's pick-list preference", "Vera wants lot code and reserved piece count on the same pick-list line. A carton symbol alone does not tell a picker how many washers to take.", kind="preference", level=2),
